        return {'load_path': 'The path to the vector field that should be loaded. Time varying data is loaded by specifying a directory.',
         'u_array_name': 'The name of the array storing the x component of the vectors.',
         'v_array_name': 'The name of the array storing the y component of the vectors.'}

    def _evaluation_logic(self, filename):
        vti = XMLImageDataReader(FileName=[filename])
        vti.PointArrayStatus = [self.u_array_name, self.v_array_name]
        vti.TimeArray = 'None'

        renameArrays = RenameArrays(Input=vti)
        renameArrays.PointArrays = [self.u_array_name, 'u', self.v_array_name, 'v']
        return Vector(renameArrays)

