from .randomness import default_rng, deterministic_rng

def hex_to_tuple(hex_str):
    return tuple(int(hex_str[i:i+2], 16) / 255 for i in (1, 3, 5))

def tuple_to_hex(color_tuple):
    if len(color_tuple) != 3:
        raise ValueError("color tuple must have exactly 3 elements")

    if all(0.0 <= c <= 1.0 for c in color_tuple):
        rgb = tuple(int(round(c * 255)) for c in color_tuple)
    elif all(0 <= c <= 255 for c in color_tuple):
        rgb = tuple(int(c) for c in color_tuple)
    else:
        raise ValueError("color tuple values must be in [0, 1] or [0, 255]")

    return "#{:02x}{:02x}{:02x}".format(*rgb)

def random_hex_color(generator=None):
    """Return a color using TopoPilot's private deterministic generator."""
    if generator is None:
        generator = default_rng()

    chars = "0123456789abcdef"
    color = "#"
    for i in range(6):
        color = color + chars[generator.randrange(len(chars))]
    return color

def random_hex_colors(count, namespace="hex-colors"):
    generator = deterministic_rng(namespace)
    return [random_hex_color(generator) for _ in range(count)]

def random_categorical_lut(categories, namespace="categorical-lut"):
    generator = deterministic_rng(namespace)
    lut = []
    for c in categories:
        lut.append(c)
        for j in range(3):
            lut.append(generator.random())

    return lut

def is_hex_string(string):
    good = (string[0] == "#" and len(string) == 7)
    for char in string[1:]:
        if char not in "1234567890abcdef":
            good = False

    return good

def color_list_to_lut(color_list):
    lut = []
    for i, color in enumerate(color_list):
        lut.append(i)
        color_tuple = hex_to_tuple(color)
        for j in range(3):
            lut.append(color_tuple[j])

    return lut
